// Give the request an id and clean field names (the form answers come from the trigger).
const f = $('Customer request form').item.json;
// One-time token that must come back with the review form: without it, a guessed ticket id is useless.
const token = () => Array.from({ length: 4 }, () => Math.random().toString(36).slice(2, 10)).join('');
return {
  json: {
    ticket_id: `T-${Date.now().toString(36).toUpperCase()}-${Math.floor(Math.random() * 1000)}`,
    review_token: token(),
    received_at: new Date().toISOString(),
    customer_name: String(f['Your name'] || '').trim().slice(0, 120),
    customer_email: String(f['Email'] || '').trim().slice(0, 200),
    order_number: String(f['Order number'] || '').trim().slice(0, 60),
    message: String(f['Your message'] || '').trim().slice(0, 5000),
  },
};

// Ask Gemini to classify the request and draft a reply, as JSON that can be checked.
const cfg = $('Config').first().json;
const t = $json;

const prompt = [
  `You help the customer support team of ${cfg.company_name}.`,
  'Classify the customer request and draft a short, polite reply in the language the customer used.',
  'The draft will be reviewed by a person before anything is sent.',
  '',
  'Rules for the draft:',
  '- Never promise a refund, a discount, a compensation, a delivery date or anything not stated below.',
  '- Never invent order details. If information is missing, ask for it.',
  '- If you are unsure, say that a colleague will check and come back to them.',
  '- No more than 120 words. Sign as the support team, in the customer\'s language (for example "L\'équipe support" in French).',
  '',
  'Confidence: how sure you are that the category is right AND that the draft can be sent as is (0 to 1).',
  '',
  `Customer name: ${t.customer_name}`,
  `Order number: ${t.order_number || 'not given'}`,
  'Message:',
  t.message,
].join('\n');

return {
  json: {
    ...t,
    request: {
      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      generationConfig: {
        temperature: 0.2,
        responseMimeType: 'application/json',
        responseSchema: {
          type: 'OBJECT',
          properties: {
            category: {
              type: 'STRING',
              enum: ['order_status', 'shipping', 'product_question', 'refund', 'complaint', 'other'],
            },
            urgency: { type: 'STRING', enum: ['low', 'normal', 'high'] },
            language: { type: 'STRING' },
            confidence: { type: 'NUMBER' },
            draft_reply: { type: 'STRING' },
          },
          required: ['category', 'urgency', 'language', 'confidence', 'draft_reply'],
        },
      },
    },
  },
};

// Guardrails decide what a human must handle alone. The AI never decides that on its own.
const cfg = $('Config').first().json;
const t = $('Build the Gemini request').item.json;

let ai = null;
const problems = [];
if ($json.error) {
  // Gemini unavailable: the customer still gets a person, never silence.
  const err = $json.error;
  problems.push(`Gemini call failed: ${String(err.message || err.description || JSON.stringify(err)).slice(0, 200)}`);
} else {
  try {
    ai = JSON.parse($json.candidates[0].content.parts[0].text);
  } catch (e) {
    problems.push('AI answer is not valid JSON');
  }
  if (!problems.length && (ai === null || typeof ai !== 'object' || Array.isArray(ai))) {
    problems.push('AI answer is not a JSON object');
    ai = null;
  }
}
const categories = ['order_status', 'shipping', 'product_question', 'refund', 'complaint', 'other'];
if (ai) {
  if (!categories.includes(ai.category)) problems.push('unknown category');
  if (typeof ai.confidence !== 'number' || ai.confidence < 0 || ai.confidence > 1) problems.push('confidence outside 0-1');
  if (!['low', 'normal', 'high'].includes(ai.urgency)) problems.push('unknown urgency');
  if (!ai.draft_reply || String(ai.draft_reply).trim().length < 20) problems.push('empty draft');
}

// Signs that a draft promises money, a discount, a guarantee or a date (English and French).
// A match sends the request to a person. False positives are acceptable; misses are not.
// Tested in tests/guardrail_words.test.js.
const risky = /(refund\w*|reimburs\w*|rembours\w*|compensat\w*|dédommag\w*|discount\w*|réduction\w*|remise\w*|coupon\w*|voucher\w*|store credit|free of charge|gratuit\w*|guarantee\w*|garanti\w*|\d+\s?(%|€|\$|usd\b|eur\b|euros?\b|fcfa\b|xof\b)|[$€]\s?\d+|\b(deliver\w*|arriv\w*|ship\w*|livr\w*|expédi\w*|recevr\w*)\b[^.!?]{0,40}\b(on|by|tomorrow|today|demain|aujourd'hui|avant|lundi|mardi|mercredi|jeudi|vendredi|samedi|dimanche|monday|tuesday|wednesday|thursday|friday|saturday|sunday|\d{1,2}))/i;

let route = 'needs_approval';
let reason = '';
if (!cfg.drafting_enabled) {
  route = 'human_only';
  reason = 'drafting is paused (drafting_enabled = false in Config)';
} else if (problems.length) {
  route = 'human_only';
  reason = $json.error ? problems[0] : `AI answer rejected: ${problems.join('; ')}`;
} else if (cfg.human_only_categories.includes(ai.category)) {
  route = 'human_only';
  reason = `sensitive topic (${ai.category}): always handled by a person`;
} else if (ai.confidence < cfg.min_confidence) {
  route = 'human_only';
  reason = `AI not confident enough (${ai.confidence} < ${cfg.min_confidence})`;
} else if (risky.test(ai.draft_reply)) {
  route = 'human_only';
  reason = 'the draft mentions money, a guarantee or a date: a person must write it';
}

// Escaped copies for the Telegram messages (sent as HTML).
const esc = (v) => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const draft = route === 'needs_approval' ? String(ai.draft_reply).slice(0, 1500) : '';
// Link to the review form (workflow 3): ticket id, one-time token, and the draft pre-filled for editing.
// Telegram does not make localhost links clickable, so the link is shown as text to copy.
// The pre-filled draft is dropped if it would make the link too long for a Telegram message.
const baseLink = `${String(cfg.n8n_url).replace(/\/$/, '')}/form/support-review` +
  `?ticket_id=${encodeURIComponent(t.ticket_id)}&token=${encodeURIComponent(t.review_token)}`;
const prefill = `&${encodeURIComponent('Reply to send')}=${encodeURIComponent(draft)}`;
const reviewLink = baseLink.length + prefill.length <= 1800 ? baseLink + prefill : baseLink;

return {
  json: {
    ...t,
    request: undefined,
    category: ai && categories.includes(ai.category) ? ai.category : 'unknown',
    urgency: ai && ['low', 'normal', 'high'].includes(ai.urgency) ? ai.urgency : 'normal',
    language: ai ? String(ai.language || '').slice(0, 30) : '',
    ai_confidence: ai && typeof ai.confidence === 'number' ? ai.confidence : null,
    route,
    route_reason: reason,
    // A draft is kept only when a human will review it.
    draft_reply: draft,
    decision: '',
    final_reply: '',
    edited: '',
    decided_at: '',
    minutes_to_decision: null,
    model: cfg.model,
    html: {
      name: esc(t.customer_name),
      email: esc(t.customer_email),
      order: esc(t.order_number || '—'),
      message: esc(t.message.slice(0, 1500)),
      draft: esc(draft),
      reason: esc(reason),
      review_link: esc(reviewLink),
    },
  },
};

